base<-"analysis/comp_assessments";db<-file.path(base,"database");cache<-file.path(base,"source_cache/ices_anchovy_west_iberia_2026")
stock_id<-"ices_anchovy_west_iberia";id<-"ices_anchovy_west_iberia_2026"; report<-"https://doi.org/10.17895/ices.pub.32614524.v2";sag<-"https://sag.ices.dk/SAG_API/StockXmlDownload/23750"
verify<-function(f,h){p<-file.path(cache,f);stopifnot(digest::digest(readBin(p,"raw",n=file.info(p)$size),serialize=FALSE,algo="sha256")==h);p}
pdf<-pdftools::pdf_text(verify("WGHANSA_2026.pdf","f4588a787acb7530ba95befbe57d4cfbc50dee7620cc73c01d24159c527d4b95")); xml<-xml2::read_xml(verify("SAG_2026_23750.xml","85fb4e3b349988288151b1599070ea33ad944d68a46e39326a891a8d44f18507"))
stopifnot(xml2::xml_text(xml2::xml_find_first(xml,"/Assessment/StockCode"))=="ane.27.9aW",xml2::xml_text(xml2::xml_find_first(xml,"/Assessment/AssessmentYear"))=="2026",xml2::xml_text(xml2::xml_find_first(xml,"/Assessment/StockSizeDescription"))=="B_index")
fish<-xml2::xml_find_all(xml,"/Assessment/Fish_Data"); field<-function(n)suppressWarnings(as.numeric(xml2::xml_text(xml2::xml_find_first(fish,n))))
y<-field("Year");idx<-field("StockSize");hr<-field("FishingPressure");stopifnot(identical(as.integer(y),1989:2026),identical(as.integer(y[is.finite(idx)]),c(2007:2011,2013:2026)),tail(idx,1)==65291)
rows<-function(text,years,n){l<-strsplit(paste(text,collapse="\n"),"\n")[[1]];l<-trimws(l[grepl("^[[:space:]]*(19|20)[0-9]{2}[[:space:]]+[0-9]",l)]);a<-lapply(strsplit(l,"[[:space:]]+"),function(z)suppressWarnings(as.numeric(z)));a<-a[lengths(a)==n & vapply(a,function(z)all(is.finite(z)),logical(1))];m<-do.call(rbind,a);m<-m[m[,1]%in%years,,drop=FALSE];stopifnot(identical(as.integer(m[,1]),years));m}
catch<-rows(pdf[31:32],1989:2025,5L)
l<-strsplit(pdf[40],"\n")[[1]];l<-l[seq.int(grep("Table 3.3.5.2.2.",l,fixed=TRUE),length(l))];age<-rows(l,c(2011L,2012L,2015:2024),5L)
stopifnot(tail(catch[,5],1)==12940,catch[catch[,1]==2024,5]==5935,age[age[,1]==2011,2]==2725,age[age[,1]==2024,3]==2467)
blank<-function(f,n=1L){cols<-names(read.csv(file.path(db,f),nrows=0));z<-as.data.frame(matrix("",n,length(cols)),stringsAsFactors=FALSE);names(z)<-cols;if("assessment_id"%in%cols)z$assessment_id<-id;z}
input<-function(type,measure,basis,year,age,value,unit,region,ref,notes,survey="",fleet="",source="official_table"){z<-blank("inputs.csv",length(value));z$type<-type;z$measure<-measure;z$basis<-basis;z$year<-year;z$year_basis<-"calendar_year";z$age<-age;z$value<-value;z$unit<-unit;z$region<-region;z$source_reference<-ref;z$notes<-notes;z$survey<-survey;z$fleet<-fleet;z$source_type<-source;z}
inputs<-input("catch","total_biomass","biomass",catch[,1],"",catch[,5],"tonnes","Western Iberian 9.a",paste(report,"Table 3.3.2.1"),"Calendar-year stock catch includes Spanish discards where available; 2020 first-semester discard sampling missing. Regional catch components overlap total and are not independent observations.",fleet="All catches")
for(k in 2:4)inputs<-rbind(inputs,input("catch","total_biomass","biomass",catch[,1],"",catch[,k],"tonnes",c("9.a North","9.a Central-North","9.a Central-South")[k-1],paste(report,"Table 3.3.2.1"),"Regional component included in the stock total; not an independent likelihood.",fleet="Regional catches"))
inputs<-rbind(inputs,input("catch","numbers_at_age","numbers",rep(age[,1],each=4),rep(0:3,times=nrow(age)),as.vector(t(age[,2:5])),"thousand fish","9.a North",paste(report,"Table 3.3.5.2.2"),"Spanish catch-at-age only, not the whole stock. Years 2013-2014 absent; 2025 excluded because this annual table conflicts with the quarterly table.",fleet="Spanish catch"),input("index","relative_biomass_index","index_scale",y[is.finite(idx)],"",idx[is.finite(idx)],"tonnes","Western Iberian 9.a",sag,"Combined spring PELACUS 9.a North plus PELAGO Central-North and Central-South biomass index; not absolute SSB. The 2012 combined index is missing; 2026 surveys were conducted in March-April.",survey="PELACUS + PELAGO",source="official_machine_readable"))
output<-function(v,measure,unit,note){ok<-is.finite(v);z<-blank("outputs.csv",sum(ok));z$type<-"index";z$measure<-measure;z$year<-y[ok];z$value<-v[ok];z$unit<-unit;z$region<-"Western Iberian 9.a";z$source_type<-"official_machine_readable";z$source_reference<-sag;z$notes<-note;z}
outputs<-rbind(output(idx,"survey_biomass_index","tonnes","Reported combined survey biomass indicator, identical to the input index, not independent estimated SSB."),output(hr,"relative_harvest_rate","ratio","ICES reported relative harvest-rate indicator; not instantaneous F. Management periods run July-June; source year labels are retained."))
a<-blank("assumptions.csv",4);a$component<-"assessment";a$setting<-c("official_method","survey_index","advice_rule","fishing_data");a$value<-c("ICES category 3.2 constant harvest rate on current survey biomass", "Combined PELACUS 9.a N and PELAGO 9.a C-N/C-S spring biomass", "HR MSY proxy 0.25; 2026 index 65291 t yields advice 16323 t for July 2026-June 2027", "Commercial catch-at-age information exists for some regions and years but does not enter an age-structured population model");a$source_reference<-paste(report,"sections 3.3-3.9");a$notes<-c("No fitted age-structured population model or stock SSB estimates for this stock.","Timing spans March-April; a single precise model timing is not reported.","Do not confuse management-year catches from SAG with calendar-year report Table 3.3.2.1.","2025 Spanish annual catch-at-age tables conflict; exact input unresolved.")
assess<-blank("assessments.csv");assess$stock_id<-stock_id;assess$assessment_year<-2026;assess$terminal_year<-2026;assess$estimate_terminal_year<-2026;assess$assessment_type<-"annual";assess$model_family<-"ICES category 3.2 constant harvest rate";assess$framework_year<-2024;assess$is_current<-"TRUE";assess$is_applied<-"TRUE";assess$assessment_url<-report;assess$data_url<-sag;assess$assumptions_status<-"partial";assess$inputs_status<-"partial";assess$outputs_status<-"partial";assess$notes<-"Current western 9.a index-based assessment, separate from southern successor and historical combined unit. Terminal year is 2026 spring survey; historical calendar catch ends 2025. No age-structured population estimates."
stock<-blank("stocks.csv");stock$stock_id<-stock_id;stock$authority<-"ICES";stock$authority_stock_id<-"ane.27.9aW";stock$scientific_name<-"Engraulis encrasicolus";stock$common_name<-"Western Iberian anchovy";stock$area<-"Western ICES division 9.a, subdivisions N, C-N and C-S";stock$region<-"Western Iberian waters";stock$ocean<-"Northeast Atlantic";stock$notes<-"Western successor to historical combined 9.a Charbonneau-Keith row ck_ices_wghansa_mordax_sp9a; southern successor is ices_anchovy_gulf_cadiz. Neither inherits the catalogue ID as a one-to-one identity."
write_rows<-function(file,z,key){p<-file.path(db,file);raw<-rawToChar(readBin(p,"raw",n=file.info(p)$size));l<-strsplit(raw,"\n",fixed=TRUE)[[1]];sel<-which(startsWith(l,paste0('"',key,'",')));stopifnot(identical(names(z),names(read.csv(p,nrows=0))));tmp<-tempfile(tmpdir=db);on.exit(unlink(tmp),add=TRUE);write.table(z,tmp,sep=",",quote=TRUE,row.names=FALSE,col.names=FALSE,na="",fileEncoding="UTF-8");repl<-readLines(tmp,encoding="UTF-8",warn=FALSE);if(length(sel)){stopifnot(identical(sel,seq.int(min(sel),max(sel))));repl<-paste0(repl,if(endsWith(l[sel[1]],"\r"))"\r" else "");l<-c(head(l,min(sel)-1L),repl,tail(l,length(l)-max(sel)))}else l<-c(l,repl);bytes<-charToRaw(paste0(paste(l,collapse="\n"),if(endsWith(raw,"\n"))"\n" else ""));if(!identical(bytes,charToRaw(raw))){writeBin(bytes,tmp);if(!file.copy(tmp,p,overwrite=TRUE))stop("write failed")}}
if(identical(Sys.getenv("TAM_SOURCE_DRY_RUN"),"1"))cat("Western Iberian 2026 source checks:",nrow(inputs),"inputs and",nrow(outputs),"indicators.\n") else {write_rows("stocks.csv",stock,stock_id);write_rows("assessments.csv",assess,id);write_rows("assumptions.csv",a,id);write_rows("inputs.csv",inputs,id);write_rows("outputs.csv",outputs,id);cat("Imported western Iberian anchovy 2026.\n")}
